mapper.select:
SELECT c.id, c.title, c.subtitle, c.cover, c.type, CASE c.type WHEN 0 THEN '视频课' WHEN 1 THEN '书本课' ELSE '未知' END AS type_text, c.difficulty, CASE c.difficulty WHEN 1 THEN '入门' WHEN 2 THEN '进阶' WHEN 3 THEN '高级' ELSE '未知' END AS difficulty_text, c.tags, c.chapter_count, c.view_count, c.is_apod_course, c.is_mars_course, CASE WHEN cf.id IS NOT NULL THEN TRUE ELSE FALSE END AS is_favorite, NULL AS last_chapter_id, ROUND((SELECT AVG(r.rating) FROM tb_course_review r WHERE r.course_id = c.id AND r.status = 1), 1) AS avg_rating, (SELECT COUNT(*) FROM tb_course_review r WHERE r.course_id = c.id AND r.status = 1) AS review_count FROM tb_course c LEFT JOIN tb_course_favorite cf ON cf.course_id = c.id AND cf.user_id = #{userId} WHERE c.status = 1 AND c.deleted = 0 AND (
c.tags LIKE CONCAT('%', #{tag}, '%')
) ORDER BY c.view_count DESC LIMIT #{limit}
